        if (!RST_N) begin
            rst_n_meta_fb <= 1'b0;
            rst_n_fb      <= 1'b0;
        end else begin
            rst_n_meta_fb <= 1'b1;
            rst_n_fb      <= rst_n_meta_fb;
        end
    end

